                            t.HasCheckConstraint("ck_writing_system_item_readings_positive_ids", "id > 0 AND writing_system_item_id > 0");

                            t.HasCheckConstraint("ck_writing_system_item_readings_sort_order", "sort_order >= 0");

                            t.HasCheckConstraint("ck_writing_system_item_readings_timestamps", "updated_at >= created_at");

                            t.HasCheckConstraint("ck_writing_system_item_readings_transcription", "length(btrim(transcription)) > 0");

                            t.HasCheckConstraint("ck_writing_system_item_readings_transcription_system", "transcription_system ~ '^[a-z][a-z0-9-]*$'");

                            t.HasCheckConstraint("ck_writing_system_item_readings_version", "version > 0");
                        });

